-- ETAPA 25: site-scoped emergency preparedness. This is not a mass-communications module.
create table public.emergency_scenarios (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,site_id uuid not null references public.sites(id) on delete restrict,code text not null check (btrim(code)<>''),name text not null check (btrim(name)<>''),description text,status text not null default 'active' check(status in ('draft','active','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(site_id,code));
create table public.emergency_resources (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,site_id uuid not null references public.sites(id) on delete restrict,resource_type text not null check(resource_type in ('first_aid','firefighting','evacuation','communication','rescue','other')),name text not null check(btrim(name)<>''),quantity integer not null default 1 check(quantity>=0),location_description text,status text not null default 'available' check(status in ('available','maintenance','unavailable','retired')),inspection_due_at date,expires_at date,evidence_document_version_id uuid references public.document_versions(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.emergency_brigades (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,site_id uuid not null references public.sites(id) on delete restrict,name text not null check(btrim(name)<>''),specialty text not null check(specialty in ('evacuation','first_aid','firefighting','rescue','mixed')),status text not null default 'active' check(status in ('active','inactive')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(site_id,name));
create table public.emergency_brigade_members (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,emergency_brigade_id uuid not null references public.emergency_brigades(id) on delete restrict,organization_member_id uuid not null references public.organization_members(id) on delete restrict,responsibility text not null default 'member' check(responsibility in ('leader','alternate','member')),active boolean not null default true,appointed_at date not null default current_date,created_at timestamptz not null default now(),unique(emergency_brigade_id,organization_member_id));
create table public.emergency_plan_versions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,site_id uuid not null references public.sites(id) on delete restrict,version_number integer not null check(version_number>0),status text not null default 'draft' check(status in ('draft','reviewed','approved','archived')),summary text not null check(btrim(summary)<>''),effective_from date,effective_to date,document_version_id uuid references public.document_versions(id) on delete restrict,approved_at timestamptz,approved_by uuid references auth.users(id) on delete set null,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(effective_to is null or effective_from is null or effective_to>=effective_from),unique(site_id,version_number));
create unique index emergency_one_current_plan_per_site_idx on public.emergency_plan_versions(site_id) where status='approved' and effective_to is null;
create table public.emergency_drills (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,site_id uuid not null references public.sites(id) on delete restrict,emergency_scenario_id uuid references public.emergency_scenarios(id) on delete restrict,emergency_plan_version_id uuid references public.emergency_plan_versions(id) on delete restrict,title text not null check(btrim(title)<>''),scheduled_at timestamptz,conducted_at timestamptz,status text not null default 'planned' check(status in ('planned','in_progress','completed','cancelled')),coordinator_user_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(conducted_at is null or scheduled_at is null or conducted_at>=scheduled_at));
create table public.emergency_drill_results (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,emergency_drill_id uuid not null unique references public.emergency_drills(id) on delete restrict,participant_count integer check(participant_count is null or participant_count>=0),duration_seconds integer check(duration_seconds is null or duration_seconds>=0),outcome text not null check(outcome in ('satisfactory','needs_improvement','unsatisfactory')),summary text not null check(btrim(summary)<>''),recorded_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.emergency_findings (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,emergency_drill_id uuid not null references public.emergency_drills(id) on delete restrict,title text not null check(btrim(title)<>''),description text,severity text not null default 'medium' check(severity in ('critical','high','medium','low')),status text not null default 'open' check(status in ('open','in_progress','resolved','dismissed')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.emergency_actions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,emergency_finding_id uuid not null references public.emergency_findings(id) on delete restrict,improvement_action_id uuid references public.improvement_actions(id) on delete set null,title text not null check(btrim(title)<>''),responsible_user_id uuid references auth.users(id) on delete set null,due_at date,status text not null default 'open' check(status in ('open','in_progress','verified','cancelled')),evidence_document_version_id uuid references public.document_versions(id) on delete restrict,verified_at timestamptz,verified_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.emergency_directory_entries (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,site_id uuid not null references public.sites(id) on delete restrict,display_name text not null check(btrim(display_name)<>''),operational_role text not null check(btrim(operational_role)<>''),contact_phone text,contact_email text,visibility text not null default 'emergency_team' check(visibility in ('emergency_team','site_staff')),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index emergency_scenarios_org_site_idx on public.emergency_scenarios(organization_id,site_id,status); create index emergency_resources_org_site_due_idx on public.emergency_resources(organization_id,site_id,inspection_due_at,expires_at); create index emergency_brigades_org_site_idx on public.emergency_brigades(organization_id,site_id); create index emergency_brigade_members_brigade_idx on public.emergency_brigade_members(emergency_brigade_id); create index emergency_brigade_members_member_idx on public.emergency_brigade_members(organization_member_id); create index emergency_plan_versions_org_site_idx on public.emergency_plan_versions(organization_id,site_id,status); create index emergency_drills_org_site_status_idx on public.emergency_drills(organization_id,site_id,status,scheduled_at); create index emergency_drills_scenario_idx on public.emergency_drills(emergency_scenario_id); create index emergency_drills_plan_idx on public.emergency_drills(emergency_plan_version_id); create index emergency_findings_drill_idx on public.emergency_findings(emergency_drill_id,status); create index emergency_actions_finding_idx on public.emergency_actions(emergency_finding_id,status); create index emergency_actions_improvement_idx on public.emergency_actions(improvement_action_id); create index emergency_directory_org_site_idx on public.emergency_directory_entries(organization_id,site_id,active);
insert into public.permissions(code,module,action,description) values ('emergencies.read','emergencies','read','Consultar preparación, planes y simulacros de emergencia.'),('emergencies.manage','emergencies','manage','Gestionar escenarios, recursos, brigadas, simulacros y hallazgos.'),('emergencies.approve','emergencies','approve','Aprobar versiones de planes de emergencia.'),('emergencies.directory_read','emergencies','directory_read','Consultar el directorio operativo de emergencia.') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.permissions p on p.code like 'emergencies.%' where r.code='organization_admin' and r.organization_id is null on conflict do nothing;
create or replace function private.validate_emergency_links() returns trigger language plpgsql security definer set search_path='' as $$ declare linked_org uuid; begin
 if tg_table_name in ('emergency_scenarios','emergency_resources','emergency_brigades','emergency_plan_versions','emergency_drills','emergency_directory_entries') then select organization_id into linked_org from public.sites where id=new.site_id;
 elsif tg_table_name='emergency_brigade_members' then select organization_id into linked_org from public.emergency_brigades where id=new.emergency_brigade_id; if linked_org is null or linked_org<>new.organization_id or not exists(select 1 from public.organization_members where id=new.organization_member_id and organization_id=new.organization_id) then raise exception 'emergency brigade member belongs to another organization' using errcode='23514'; end if; return new;
 elsif tg_table_name='emergency_drill_results' then select organization_id into linked_org from public.emergency_drills where id=new.emergency_drill_id;
 elsif tg_table_name='emergency_findings' then select organization_id into linked_org from public.emergency_drills where id=new.emergency_drill_id;
 elsif tg_table_name='emergency_actions' then select organization_id into linked_org from public.emergency_findings where id=new.emergency_finding_id; if linked_org is null or linked_org<>new.organization_id then raise exception 'emergency action finding belongs to another organization' using errcode='23514'; end if; if new.improvement_action_id is not null and not exists(select 1 from public.improvement_actions where id=new.improvement_action_id and organization_id=new.organization_id) then raise exception 'emergency action improvement link belongs to another organization' using errcode='23514'; end if; if new.evidence_document_version_id is not null and not exists(select 1 from public.document_versions where id=new.evidence_document_version_id and organization_id=new.organization_id) then raise exception 'emergency action evidence belongs to another organization' using errcode='23514'; end if; return new; end if;
 if linked_org is null or linked_org<>new.organization_id then raise exception 'emergency record belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='emergency_plan_versions' and new.document_version_id is not null and not exists(select 1 from public.document_versions where id=new.document_version_id and organization_id=new.organization_id) then raise exception 'emergency plan evidence belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='emergency_drills' and ((new.emergency_scenario_id is not null and not exists(select 1 from public.emergency_scenarios where id=new.emergency_scenario_id and organization_id=new.organization_id and site_id=new.site_id)) or (new.emergency_plan_version_id is not null and not exists(select 1 from public.emergency_plan_versions where id=new.emergency_plan_version_id and organization_id=new.organization_id and site_id=new.site_id))) then raise exception 'emergency drill dependency belongs to another site or organization' using errcode='23514'; end if; return new; end; $$;
create or replace function private.validate_emergency_plan_transition() returns trigger language plpgsql security definer set search_path='' as $$ begin if old.status='archived' and row(new.*) is distinct from row(old.*) then raise exception 'archived emergency plan versions are immutable' using errcode='55000'; end if; if new.status='approved' and old.status<>'approved' then if not private.has_permission(new.organization_id,'emergencies.approve') then raise exception 'emergency plan approval permission required' using errcode='42501'; end if; new.approved_at:=now(); new.approved_by:=(select auth.uid()); end if; return new; end; $$;
create or replace function private.validate_emergency_action_transition() returns trigger language plpgsql security definer set search_path='' as $$ begin if old.status='verified' and row(new.*) is distinct from row(old.*) then raise exception 'verified emergency actions are immutable' using errcode='55000'; end if; if new.status='verified' and old.status<>'verified' then if new.evidence_document_version_id is null then raise exception 'evidence is required before verification' using errcode='23514'; end if; if not private.has_permission(new.organization_id,'emergencies.approve') then raise exception 'emergency action verification permission required' using errcode='42501'; end if; new.verified_at:=now(); new.verified_by:=(select auth.uid()); end if; return new; end; $$;
create or replace function private.emit_emergency_drill_completed() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.status='completed' and (tg_op='INSERT' or old.status<>'completed') then perform private.enqueue_domain_event(new.organization_id,'emergency.drill.completed','emergency_drill',new.id,jsonb_build_object('site_id',new.site_id,'scenario_id',new.emergency_scenario_id),new.id); end if; return new; end; $$;
revoke all on function private.validate_emergency_links(),private.validate_emergency_plan_transition(),private.validate_emergency_action_transition(),private.emit_emergency_drill_completed() from public,anon,authenticated,service_role;
alter table public.emergency_scenarios enable row level security; alter table public.emergency_resources enable row level security; alter table public.emergency_brigades enable row level security; alter table public.emergency_brigade_members enable row level security; alter table public.emergency_plan_versions enable row level security; alter table public.emergency_drills enable row level security; alter table public.emergency_drill_results enable row level security; alter table public.emergency_findings enable row level security; alter table public.emergency_actions enable row level security; alter table public.emergency_directory_entries enable row level security;
grant select,insert,update on public.emergency_scenarios,public.emergency_resources,public.emergency_brigades,public.emergency_brigade_members,public.emergency_plan_versions,public.emergency_drills,public.emergency_drill_results,public.emergency_findings,public.emergency_actions,public.emergency_directory_entries to authenticated;
create policy emergency_scenarios_read on public.emergency_scenarios for select to authenticated using((select private.has_permission(organization_id,'emergencies.read'))); create policy emergency_scenarios_write on public.emergency_scenarios for all to authenticated using((select private.has_permission(organization_id,'emergencies.manage'))) with check((select private.has_permission(organization_id,'emergencies.manage')));
create policy emergency_resources_read on public.emergency_resources for select to authenticated using((select private.has_permission(organization_id,'emergencies.read'))); create policy emergency_resources_write on public.emergency_resources for all to authenticated using((select private.has_permission(organization_id,'emergencies.manage'))) with check((select private.has_permission(organization_id,'emergencies.manage')));
create policy emergency_brigades_read on public.emergency_brigades for select to authenticated using((select private.has_permission(organization_id,'emergencies.read'))); create policy emergency_brigades_write on public.emergency_brigades for all to authenticated using((select private.has_permission(organization_id,'emergencies.manage'))) with check((select private.has_permission(organization_id,'emergencies.manage')));
create policy emergency_brigade_members_read on public.emergency_brigade_members for select to authenticated using((select private.has_permission(organization_id,'emergencies.read'))); create policy emergency_brigade_members_write on public.emergency_brigade_members for all to authenticated using((select private.has_permission(organization_id,'emergencies.manage'))) with check((select private.has_permission(organization_id,'emergencies.manage')));
create policy emergency_plan_versions_read on public.emergency_plan_versions for select to authenticated using((select private.has_permission(organization_id,'emergencies.read'))); create policy emergency_plan_versions_write on public.emergency_plan_versions for all to authenticated using((select private.has_permission(organization_id,'emergencies.manage'))) with check((select private.has_permission(organization_id,'emergencies.manage')));
create policy emergency_drills_read on public.emergency_drills for select to authenticated using((select private.has_permission(organization_id,'emergencies.read'))); create policy emergency_drills_write on public.emergency_drills for all to authenticated using((select private.has_permission(organization_id,'emergencies.manage'))) with check((select private.has_permission(organization_id,'emergencies.manage')));
create policy emergency_drill_results_read on public.emergency_drill_results for select to authenticated using((select private.has_permission(organization_id,'emergencies.read'))); create policy emergency_drill_results_write on public.emergency_drill_results for all to authenticated using((select private.has_permission(organization_id,'emergencies.manage'))) with check((select private.has_permission(organization_id,'emergencies.manage')));
create policy emergency_findings_read on public.emergency_findings for select to authenticated using((select private.has_permission(organization_id,'emergencies.read'))); create policy emergency_findings_write on public.emergency_findings for all to authenticated using((select private.has_permission(organization_id,'emergencies.manage'))) with check((select private.has_permission(organization_id,'emergencies.manage')));
create policy emergency_actions_read on public.emergency_actions for select to authenticated using((select private.has_permission(organization_id,'emergencies.read'))); create policy emergency_actions_write on public.emergency_actions for all to authenticated using((select private.has_permission(organization_id,'emergencies.manage'))) with check((select private.has_permission(organization_id,'emergencies.manage')));
create policy emergency_directory_read on public.emergency_directory_entries for select to authenticated using((select private.has_permission(organization_id,'emergencies.directory_read'))); create policy emergency_directory_write on public.emergency_directory_entries for all to authenticated using((select private.has_permission(organization_id,'emergencies.manage'))) with check((select private.has_permission(organization_id,'emergencies.manage')));
create view public.emergency_resilient_directory with (security_invoker=true) as select id,organization_id,site_id,display_name,operational_role,contact_phone,contact_email,visibility,updated_at from public.emergency_directory_entries where active=true; grant select on public.emergency_resilient_directory to authenticated;
create trigger emergency_scenarios_links before insert or update on public.emergency_scenarios for each row execute function private.validate_emergency_links(); create trigger emergency_resources_links before insert or update on public.emergency_resources for each row execute function private.validate_emergency_links(); create trigger emergency_brigades_links before insert or update on public.emergency_brigades for each row execute function private.validate_emergency_links(); create trigger emergency_brigade_members_links before insert or update on public.emergency_brigade_members for each row execute function private.validate_emergency_links(); create trigger emergency_plan_links before insert or update on public.emergency_plan_versions for each row execute function private.validate_emergency_links(); create trigger emergency_drills_links before insert or update on public.emergency_drills for each row execute function private.validate_emergency_links(); create trigger emergency_results_links before insert or update on public.emergency_drill_results for each row execute function private.validate_emergency_links(); create trigger emergency_findings_links before insert or update on public.emergency_findings for each row execute function private.validate_emergency_links(); create trigger emergency_actions_links before insert or update on public.emergency_actions for each row execute function private.validate_emergency_links(); create trigger emergency_directory_links before insert or update on public.emergency_directory_entries for each row execute function private.validate_emergency_links(); create trigger emergency_plan_transition before update on public.emergency_plan_versions for each row execute function private.validate_emergency_plan_transition(); create trigger emergency_action_transition before update on public.emergency_actions for each row execute function private.validate_emergency_action_transition(); create trigger emergency_drill_completed after insert or update of status on public.emergency_drills for each row execute function private.emit_emergency_drill_completed();
create trigger emergency_scenarios_updated before update on public.emergency_scenarios for each row execute function private.set_updated_at(); create trigger emergency_resources_updated before update on public.emergency_resources for each row execute function private.set_updated_at(); create trigger emergency_brigades_updated before update on public.emergency_brigades for each row execute function private.set_updated_at(); create trigger emergency_plans_updated before update on public.emergency_plan_versions for each row execute function private.set_updated_at(); create trigger emergency_drills_updated before update on public.emergency_drills for each row execute function private.set_updated_at(); create trigger emergency_results_updated before update on public.emergency_drill_results for each row execute function private.set_updated_at(); create trigger emergency_findings_updated before update on public.emergency_findings for each row execute function private.set_updated_at(); create trigger emergency_actions_updated before update on public.emergency_actions for each row execute function private.set_updated_at(); create trigger emergency_directory_updated before update on public.emergency_directory_entries for each row execute function private.set_updated_at();
create trigger emergency_plans_audit after insert or update on public.emergency_plan_versions for each row execute function private.capture_core_audit(); create trigger emergency_drills_audit after insert or update on public.emergency_drills for each row execute function private.capture_core_audit(); create trigger emergency_results_audit after insert or update on public.emergency_drill_results for each row execute function private.capture_core_audit(); create trigger emergency_findings_audit after insert or update on public.emergency_findings for each row execute function private.capture_core_audit(); create trigger emergency_actions_audit after insert or update on public.emergency_actions for each row execute function private.capture_core_audit();
notify pgrst,'reload schema';
